internal static class FittingClipboard
{
 [DllImport("SDL2",EntryPoint="SDL_SetClipboardText")]static extern int SetWin([MarshalAs(UnmanagedType.LPUTF8Str)]string text);
 [DllImport("SDL2",EntryPoint="SDL_GetClipboardText")]static extern IntPtr GetWin();
 [DllImport("SDL2",EntryPoint="SDL_free")]static extern void FreeWin(IntPtr ptr);
 [DllImport("libSDL2-2.0.so.0",EntryPoint="SDL_SetClipboardText")]static extern int SetLinux([MarshalAs(UnmanagedType.LPUTF8Str)]string text);
 [DllImport("libSDL2-2.0.so.0",EntryPoint="SDL_GetClipboardText")]static extern IntPtr GetLinux();
 [DllImport("libSDL2-2.0.so.0",EntryPoint="SDL_free")]static extern void FreeLinux(IntPtr ptr);
 internal static void Set(string s){if((OperatingSystem.IsWindows()?SetWin(s):SetLinux(s))!=0)throw new IOException("Clipboard unavailable");}
 internal static string Get(){var p=OperatingSystem.IsWindows()?GetWin():GetLinux();if(p==IntPtr.Zero)throw new IOException("Clipboard unavailable");try{return Marshal.PtrToStringUTF8(p)??"";}finally{if(OperatingSystem.IsWindows())FreeWin(p);else FreeLinux(p);}}
}
